import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.BvlN9b-o.js";const c=JSON.parse('{"title":"跟做：搜索标题与安全预览","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/search-preview.md","filePath":"tutorials/search-preview.md"}'),r={name:"tutorials/search-preview.md"};function n(l,e,o,d,h,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="跟做-搜索标题与安全预览" tabindex="-1">跟做：搜索标题与安全预览 <a class="header-anchor" href="#跟做-搜索标题与安全预览" aria-label="Permalink to &quot;跟做：搜索标题与安全预览&quot;">​</a></h1><p>运行 <code>just dev</code>，登录后新建标题为“部署 100%_完成”的文档，在正文填写：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 部署笔记</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**检查列表**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">：</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] 数据库可连接</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ ] 发布应用</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">参见 [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Rust 官网</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">https://www.rust-lang.org/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)。</span></span></code></pre></div><p>切换“预览”查看排版，再保存。阅读页显示同样的安全渲染结果。返回“我的文档”，输入 <code>100%_</code> 并按 Enter，能找到刚才的文档；这里的 <code>%</code>、<code>_</code> 都是普通字符。清除搜索恢复列表。更多结果使用“加载更多”，更换关键词或重新提交搜索从第一页开始。</p><h2 id="_1-给现有列表增加筛选" tabindex="-1">1. 给现有列表增加筛选 <a class="header-anchor" href="#_1-给现有列表增加筛选" aria-label="Permalink to &quot;1. 给现有列表增加筛选&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/7d900df4a752e8b6b99730573d0e84926e27de0f/crates/app/src/modules/knowledge/mod.rs" target="_blank" rel="noreferrer">HTTP 合同</a>在原来的列表接口增加可选 <code>q</code>，保持只返回摘要。关键词最多 200 个 Unicode 字符，不能包含 NUL；去掉两端空白后进行不区分大小写的标题子串匹配。空关键词显示个人库全部可访问文档。创建标题仍限制为 1–200 字符，正文 UTF-8 编码后最多 1 MiB；浏览器提供即时反馈，服务端继续独立验证。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/7d900df4a752e8b6b99730573d0e84926e27de0f/crates/app/src/modules/knowledge/application.rs" target="_blank" rel="noreferrer">Application</a>转义 LIKE 的 <code>%</code>、<code>_</code>、反斜杠，然后把模式作为 SQL 参数绑定。不要拼接用户输入成为 SQL，更不要把 <code>%</code> 当作用户可以控制的通配符。</p><p>当前接口的范围是“我的个人知识库”。后续知识库授权页面将提供库范围的浏览入口；这里不会因为 Owner 有读取权限，就把全企业文档混进“我的文档”。权限条件、关键词、分页边界一起进入查询，无权访问的标题不会先查询出来再由浏览器过滤。</p><h2 id="_2-游标绑定查询条件" tabindex="-1">2. 游标绑定查询条件 <a class="header-anchor" href="#_2-游标绑定查询条件" aria-label="Permalink to &quot;2. 游标绑定查询条件&quot;">​</a></h2><p>分页按 <code>created_at DESC, id DESC</code> 排序。新文档插入不会把下一页已有记录推回上一页。<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/7d900df4a752e8b6b99730573d0e84926e27de0f/crates/app/src/modules/knowledge/pagination.rs" target="_blank" rel="noreferrer">Cursor</a>包含当前身份、范围/排序、规范化关键词的摘要和末条位置，换身份或关键词必须重新查询。每一页都重新检查当前 Grant；游标只是位置，不是授权凭据，也不保证跨页数据库快照。</p><p><code>limit</code> 默认 50、最大 100，服务端多取一条判断 <code>has_more</code>，不返回总数或正文。非法游标返回结构化 400；网络失败保留请求编号，页面提供重新查询或重试下一页。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/7d900df4a752e8b6b99730573d0e84926e27de0f/packages/views/src/knowledge/documents-view.tsx" target="_blank" rel="noreferrer">View</a>使用 TanStack Query，key 包含身份、个人库范围和关键词；已保存文档仍只在 Query 缓存中。搜索输入是表单状态，预览是未保存草稿的展示，不另建资源 store。换身份会清缓存并重建搜索表单。列表内存最多保留十页，超过后按窗口移出最早页，重新搜索可从头开始。</p><h2 id="_3-把不可信-markdown-当内容" tabindex="-1">3. 把不可信 Markdown 当内容 <a class="header-anchor" href="#_3-把不可信-markdown-当内容" aria-label="Permalink to &quot;3. 把不可信 Markdown 当内容&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/7d900df4a752e8b6b99730573d0e84926e27de0f/packages/views/src/knowledge/markdown-content.tsx" target="_blank" rel="noreferrer">Markdown 渲染器</a>使用固定版本的 <code>react-markdown</code>、<code>remark-gfm</code>、<code>rehype-sanitize</code>：</p><ul><li><code>skipHtml</code> 禁用原始 HTML，不启用 <code>rehype-raw</code>。</li><li>保留默认 URL 协议过滤，再用默认 sanitize schema 清洗；被过滤的链接显示普通文字。</li><li>支持标题、列表、强调、代码、链接、表格和任务清单。</li><li>外链通过普通浏览器链接打开，使用 <code>noopener noreferrer</code>；服务端不抓取链接。</li><li>当前图片显示替代文字，不自动加载外部图片；附件章节会接入授权资源引用，不能把永久公开存储 URL 写进正文。</li></ul><p>“编辑”面板保留原始输入；只有切到“预览”时才取一次正文。解析器通过动态 import 按需加载，不在注册页面加载或每个按键重新解析。超过 1 MiB 的草稿不能预览或提交，但输入保留，用户可以缩减后重试。新增 Markdown 插件时要重新审查其是否生成未经清洗的 HTML/URL。</p><h2 id="_4-从公开入口验证" tabindex="-1">4. 从公开入口验证 <a class="header-anchor" href="#_4-从公开入口验证" aria-label="Permalink to &quot;4. 从公开入口验证&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> knowledge</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/knowledge.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>HTTP 测试使用真实 PostgreSQL，验证字面转义、排序、筛选绑定、输入上限、跨账号不可见和撤权后继续翻页。View 测试从真实页面操作，覆盖键盘切换、安全链接、草稿保留、分页失败重试、空结果和重新查询。</p><p>关键旅程完成后运行一次：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/e2e.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/knowledge.spec.ts</span></span></code></pre></div><p>真实 Chromium 从注册 Member、写作预览、保存、刷新，再通过标题搜索打开正文。日常修改运行定向 HTTP/View 测试，无需每次推送重复浏览器旅程。</p><h2 id="_5-仿照实现自己的业务" tabindex="-1">5. 仿照实现自己的业务 <a class="header-anchor" href="#_5-仿照实现自己的业务" aria-label="Permalink to &quot;5. 仿照实现自己的业务&quot;">​</a></h2><p>在自己的列表合同增加有界筛选，参数化查询并在 cursor 与 Query key 中包含同一筛选；由服务端完成授权。把内容格式转换放在业务 View 边界，而不是 Core 会话或通用 SDK 中。</p><p>本章源码、测试、生成的 Knowledge 操作和教程都归知识库示例；通用 Tabs 是可复用 UI。<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/7d900df4a752e8b6b99730573d0e84926e27de0f/examples/knowledge-base/manifest.json" target="_blank" rel="noreferrer">所有权清单</a>记录移除范围。Markdown 依赖仅由示例 Views 使用，删例工具会移除这组依赖登记。</p><p>库文档： <a href="https://github.com/remarkjs/react-markdown/tree/10.1.0#security" target="_blank" rel="noreferrer">react-markdown 10.1.0</a>、<a href="https://github.com/remarkjs/remark-gfm/tree/4.0.1" target="_blank" rel="noreferrer">remark-gfm 4.0.1</a>、<a href="https://github.com/rehypejs/rehype-sanitize/tree/6.0.0" target="_blank" rel="noreferrer">rehype-sanitize 6.0.0</a>。</p><hr><p>源码版本：<code>7d900df4a752</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/7d900df4a752e8b6b99730573d0e84926e27de0f/docs/tutorials/05-search-preview.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,28)])])}const g=a(r,[["render",n]]);export{c as __pageData,g as default};
